-- @EXT_DB@ 
select
 NAME, ADDRESS, IS_HOGE, BIRTH_DATE, INT_VAL, TRAN_TIME, TRAN_TIME_WITH_TZ, TRAN_TIME_WITH_LTZ
 from
 EMPLOYEE4
 where
	/*IF pmb.BIRTH_DATE != null*/
	BIRTH_DATE = /*pmb.BIRTH_DATE*/'2021/01/02 0:00:00'
	/*END*/
	/*IF pmb.TRAN_TIME != null*/
	and TRAN_TIME = /*pmb.TRAN_TIME*/'2022/01/02 0:00:00'
	/*END*/
	/*IF pmb.TRAN_TIME_WITH_TZ != null*/
	and TRAN_TIME_WITH_TZ = /*pmb.TRAN_TIME_WITH_TZ*/'23-01-02 00:00:00.000000 +10:00'
	/*END*/
	/*IF pmb.TRAN_TIME_WITH_LTZ != null*/
	and TRAN_TIME_WITH_LTZ = /*pmb.TRAN_TIME_WITH_LTZ*/'24-01-02 00:00:00.000000'
	/*END*/
 order by NAME
